\"\"\"Minimal, stdlib-only client for OpenAI's Responses API.

Prompts are sent with "'``store=False`` by default so OpenAI does not retain
the response for later retrieval. The API key is read from the
``OPENAI_API_KEY`` environment variable unless passed explicitly, and is
never logged or written to disk.

Example:
    from openai_client import OpenAIClient
    client = OpenAIClient()
    print(client.ask("Summarize the plot of Hamlet in one sentence."))
"""

import json
import os
import ssl
import sys
import urllib.error
import urllib.request

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(Exception):
    """Raised when the API returns an error or an unexpected response."""

    def __init__(self, message, status=None, body=None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    def __init__(self, api_key=None, model=DEFAULT_MODEL, base_url=DEFAULT_BASE_URL,
                 timeout=60.0, organization=None, project=None):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError("No API key: pass api_key or set OPENAI_API_KEY.")
        self.model = model
        self.base_url = base_url.rstrip("/")
        if not self.base_url.startswith("https://"):
            raise OpenAIError("base_url must use https:// to protect prompts in transit.")
        self.timeout = timeout
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")
        self.project = project or os.environ.get("OPENAI_PROJECT_ID")
        self._ssl_context = ssl.create_default_context()

    def __repr__(self):
        return f"OpenAIClient(model={self.model!r}, base_url={self.base_url!r})"

    def _headers(self):
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project
        return headers

    def create_response(self, prompt, *, instructions=None, model=None, store=False,
                        **extra):
        """POST /responses and return the parsed JSON response dict.

        ``prompt`` may be a string or a list of input items. Extra keyword
        arguments (e.g. ``temperature``, ``max_output_tokens``) are passed
        through in the request body.
        """
        payload = {"model": model or self.model, "input": prompt, "store": store}
        if instructions is not None:
            payload["instructions"] = instructions
        payload.update(extra)

        request = urllib.request.Request(
            f"{self.base_url}/responses",
            data=json.dumps(payload).encode("utf-8"),
            headers=self._headers(),
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout,
                                        context=self._ssl_context) as resp:
                raw = resp.read().decode("utf-8")
        except urllib.error.HTTPError as err:
            body = err.read().decode("utf-8", errors="replace")
            message = body
            try:
                message = json.loads(body)["error"]["message"]
            except (ValueError, KeyError, TypeError):
                pass
            raise OpenAIError(f"HTTP {err.code}: {message}", status=err.code,
                              body=body) from None
        except urllib.error.URLError as err:
            raise OpenAIError(f"Connection error: {err.reason}") from None

        try:
            data = json.loads(raw)
        except ValueError:
            raise OpenAIError("Invalid JSON in API response.", body=raw) from None
        if data.get("error"):
            raise OpenAIError(str(data["error"]), body=raw)
        return data

    @staticmethod
    def extract_text(response):
        """Concatenate all output_text parts from a Responses API result."""
        if isinstance(response.get("output_text"), str):
            return response["output_text"]
        parts = []
        for item in response.get("output", []):
            if item.get("type") != "message":
                continue
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    parts.append(content.get("text", ""))
        return "".join(parts)

    def ask(self, prompt, **kwargs):
        """Send a text prompt and return the model'"'s text reply.\"\"\"
        return self.extract_text(self.create_response(prompt, **kwargs))


def main(argv=None):
    import argparse

    parser = argparse.ArgumentParser(description=\"Send a private prompt to the OpenAI Responses API.\")
    parser.add_argument(\"prompt\", nargs=\"?\", help=\"Prompt text (read from stdin if omitted).\")
    parser.add_argument(\"--model\", default=DEFAULT_MODEL)
    parser.add_argument(\"--instructions\")
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    try:
        client = OpenAIClient(model=args.model)
        print(client.ask(prompt, instructions=args.instructions))
    except OpenAIError as err:
        print(f\"Error: {err}\", file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    sys.exit(main())
